import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be printed in full.
SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}


def _parse_value(raw):
    value = raw.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8-sig") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export ") or line.startswith("export\t"):
                line = line[len("export"):].lstrip()
            key, sep, raw = line.partition("=")
            key = key.strip()
            if not sep or not key:
                continue
            values[key] = _parse_value(raw)
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def mask(key, value):
    """Return a printable form of a setting value that hides secrets."""
    if value is None:
        return "<not set>"
    if key in SECRET_KEYS:
        return f"<hidden, {len(value)} chars>"
    return value


def doctor_report(environ=None, dotenv_path=".env"):
    """Return the lines printed by `python -m payhook doctor`."""
    config = load_config(environ=environ, dotenv_path=dotenv_path)
    lines = [
        "payhook configuration",
        f"dotenv file: {os.path.abspath(dotenv_path)} "
        f"({'found' if os.path.exists(dotenv_path) else 'not found'})",
        "",
    ]
    for key, (value, source) in config.items():
        lines.append(f"{key} = {mask(key, value)}  [source: {source}]")
    missing = [key for key, (value, _) in config.items() if value is None]
    lines.append("")
    lines.append("missing required: " + (", ".join(missing) if missing else "none"))
    return lines

